function solve(operations) {
    const makeCounter = () => {
        let count = 0;
        return {
            inc() { count += 1; },
            dec() { count -= 1; },
            reset() { count = 0; },
            get() { return count; }
        };
    };
    const counter = makeCounter();
    const out = [];
    for (const op of operations) {
        if (op === 'get') out.push(counter.get());
        else counter[op]();
    }
    return out;
}

