function solve(nums, rule) {
    const rules = {
        positive: (x) => x > 0,
        even: (x) => x % 2 === 0,
        negative: (x) => x < 0
    };
    const test = rules[rule];
    let i = 0;
    while (i < nums.length && test(nums[i])) i += 1;
    return nums.slice(0, i);
}

