function solve(calls) {
    const cache = new Map();
    let computations = 0;
    const fib = (n) => {
        if (cache.has(n)) return cache.get(n);
        computations += 1;
        const value = n < 2 ? n : fib(n - 1) + fib(n - 2);
        cache.set(n, value);
        return value;
    };
    const results = calls.map((n) => fib(n));
    return { results, computations };
}

