function solve(arity, chunks) {
    const curry = (collected) => (...args) => {
        const all = collected.concat(args);
        if (all.length >= arity) return all.slice(0, arity).reduce((sum, x) => sum + x, 0);
        return curry(all);
    };
    let current = curry([]);
    for (const chunk of chunks) {
        const result = current(...chunk);
        if (typeof result === 'number') return result;
        current = result;
    }
    return null;
}

