function solve(records, spec) {
    return [...records].sort((a, b) => {
        for (const [key, direction] of spec) {
            let cmp = a[key] < b[key] ? -1 : a[key] > b[key] ? 1 : 0;
            if (direction === 'desc') cmp = -cmp;
            if (cmp !== 0) return cmp;
        }
        return 0;
    });
}
